import{_ as a,c as t,o as r,ag as n}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"Conversation History, Summaries and Checked Workflows — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/applied-ai/chapters/history-and-workflows.md","filePath":"practice/applied-ai/chapters/history-and-workflows.md"}'),i={name:"practice/applied-ai/chapters/history-and-workflows.md"};function o(s,e,c,d,p,l){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="conversation-history-summaries-and-checked-workflows-—-practice" tabindex="-1">Conversation History, Summaries and Checked Workflows — practice <a class="header-anchor" href="#conversation-history-summaries-and-checked-workflows-—-practice" aria-label="Permalink to “Conversation History, Summaries and Checked Workflows — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These requirements were separated from the textbook. Use the <a href="./../">integrated sequence</a> and shared evidence record; running reference checks is not independent completion.</p><p><a href="./../../../python-for-ai/history-and-workflows.html">Textbook</a></p><h2 id="practice-and-acceptance" tabindex="-1"><span class="hub-section-number">1 </span>Practice and acceptance <a class="header-anchor" href="#practice-and-acceptance" aria-label="Permalink to “1 Practice and acceptance”">​</a></h2><p>Run strict typing and deterministic history tests:0/1/4/6 retained turns, complete pair/order preservation, excessive input, invalid keep/bool, blank/oversize/invalid-Unicode text, fake role delimiters staying data and stable/changing digests. These establish bounded serialization only, not authorization, summarization quality or tokens.</p><p>Build an application-owned checkpoint fixture for the document assistant. Interrupt after source resolution and again after answer validation. Resume against the same revision, then against a changed source/permission/conversation revision; require reuse only for still-valid artifacts and no unauthorized disclosure. Retain stage inputs/outputs as approved fixture data, not raw private production logs. Measure stage and total latency/cost plus errors; compare the fixed workflow with one larger prompt under the same held-out task rather than assuming decomposition wins.</p><p>Create a labeled summary set containing negation, rejected options, explicit budgets, changed decisions, unresolved questions and embedded commands. For each candidate check factual support, constraint retention and source references with a human rubric. Acceptance: no permission is granted from summary text, contradictions are caught before use, omission is explicit and stale revision cannot overwrite current state. Test a final request&#39;s count/generation equality after adding history. Native UI recovery, durable store/CAS/deletion, actual provider summary quality and independent learner implementation remain required.</p>',7)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
